	@ParameterizedTest
	@CsvSource({ "0,100,100", "100,100,100", "200,100,100", "300,100,0", "0,0,300", "100,0,200", "200,0,100" })
	void pageTotalsDescribeAllMatchesAcrossOffsetsAndLimits(int offset, int limit, int returnedRows) throws Exception {
		addSubjectMatches(300);
		List<String> expectedPage = matchingValues().stream()
				.skip(offset)
				.limit(limit == 0 ? Long.MAX_VALUE : limit)
				.toList();
		MockHttpServletRequest request = pageRequest("<urn:test:subject>");
		request.addParameter("offset", Integer.toString(offset));
		request.addParameter("limit_explore", Integer.toString(limit));
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(request, response);

		List<JsonNode> records = records(response);
		assertResultTotal(records, 300);
		List<JsonNode> rows = rows(records);
		assertThat(rows).hasSize(returnedRows);
		assertThat(rows).extracting(row -> row.get(2).path("value").asText()).doesNotHaveDuplicates();
		assertThat(rows).extracting(row -> row.get(2).path("value").asText()).containsExactlyElementsOf(expectedPage);
		assertThat(rows).allSatisfy(row -> {
			assertThat(row.get(0).path("value").asText()).isEqualTo("urn:test:subject");
			assertThat(row.get(1).path("value").asText()).isEqualTo("urn:test:predicate");
			assertThat(row.get(3).isNull()).isTrue();
		});
	}

