	private void addSubjectMatches(int total) {
		ValueFactory factory = repository.getValueFactory();
		IRI subject = factory.createIRI("urn:test:subject");
		IRI predicate = factory.createIRI("urn:test:predicate");
		try (RepositoryConnection connection = repository.getConnection()) {
			for (int i = 0; i < total; i++) {
				connection.add(subject, predicate, factory.createLiteral("value-" + i));
			}
		}
	}

	private List<String> matchingValues() {
		List<String> values = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection();
				var statements = connection.getStatements(repository.getValueFactory().createIRI("urn:test:subject"),
						null, null, true)) {
			while (statements.hasNext()) {
				values.add(statements.next().getObject().stringValue());
			}
		}
		return values;
	}

	private static void assertResultTotal(List<JsonNode> records, int expectedTotal) {
		List<String> types = records.stream().map(record -> record.path("type").asText()).toList();
		assertThat(types).allSatisfy(type -> assertThat(type).isIn("head", "view", "vars", "links", "namespaces",
				"metadata", "rows", "end"));
		assertThat(types).containsOnlyOnce("head", "view", "vars", "links", "metadata", "end");
		assertThat(types.getFirst()).isEqualTo("head");
		assertThat(types.getLast()).isEqualTo("end");
		assertThat(records.stream().filter(record -> "metadata".equals(record.path("type").asText())).toList())
				.singleElement()
				.satisfies(metadata -> {
					JsonNode total = metadata.path("values").path("total-result-count");
					assertThat(total.isIntegralNumber()).isTrue();
					assertThat(total.asInt()).isEqualTo(expectedTotal);
				});
		if (types.contains("rows")) {
			assertThat(types.indexOf("metadata")).isLessThan(types.indexOf("rows"));
		}
		JsonNode terminalTotal = records.getLast().path("metadata").path("total-result-count");
		assertThat(terminalTotal.isIntegralNumber()).isTrue();
		assertThat(terminalTotal.asInt()).isEqualTo(expectedTotal);
	}

	private static List<JsonNode> rows(List<JsonNode> records) {
		List<JsonNode> rows = new ArrayList<>();
		for (JsonNode record : records) {
			if ("rows".equals(record.path("type").asText())) {
				record.path("values").forEach(rows::add);
			}
		}
		return rows;
	}

