	@ParameterizedTest
	@MethodSource("escapedResourceLiterals")
	void escapedLiteralResourcesFindTheOriginalRdfValue(Literal literal) throws Exception {
		ValueFactory factory = repository.getValueFactory();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(factory.createIRI("urn:test:subject"), factory.createIRI("urn:test:predicate"), literal);
		}
		String suffix = literal.getLanguage()
				.map(language -> "@" + language)
				.orElse(XSD.STRING.equals(literal.getDatatype()) ? "" : "^^<" + literal.getDatatype() + ">");
		String resource = JSON_MAPPER.writeValueAsString(literal.getLabel()) + suffix;
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(pageRequest(resource), response);

		List<JsonNode> records = records(response);
		assertThat(records).extracting(record -> record.path("type").asText())
				.containsExactly("head", "view", "vars", "links", "metadata", "rows", "end");
		assertResultTotal(records, 1);
		assertThat(rows(records)).singleElement()
				.satisfies(row -> assertThat(row.get(2).path("value").asText()).isEqualTo(literal.getLabel()));
	}

	private static Stream<Literal> escapedResourceLiterals() {
		ValueFactory factory = SimpleValueFactory.getInstance();
		return Stream.of("quote \" and backslash \\", "line\nwith\ttabs\rand CR", "controls\b\f\n")
				.flatMap(label -> Stream.of(factory.createLiteral(label), factory.createLiteral(label, "en-US"),
						factory.createLiteral(label, XSD.TOKEN)));
	}

